1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUM_BY_ITEM_TYPE = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	} as const satisfies Record<string, number>;
51	
52	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
53	
54	const basePremiumOf = (item: Item): number =>
55	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
56	
57	const sumBasePremiums = (items: Item[]): number =>
58	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
59	
60	const quotePremium = (items: Item[]): number => {
61	  const base = sumBasePremiums(items);
62	  const surcharge = percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
63	  return Math.ceil(base + surcharge + PROCESSING_FEE);
64	};
65	
66	const runStep = (step: Step): StepResult => {
67	  if (step.op === "quote") return { premium: quotePremium(step.items) };
68	  throw new Error("claim steps are not implemented yet");
69	};
70	
71	export const runScenario = (scenario: Scenario): ScenarioResult => ({
72	  results: scenario.steps.map(runStep),
73	});
